// t_work_order_lines has no module or number series of its own (by design — it's
// wired into this screen, not a standalone module), so its refs are derived from
// the parent work order ref rather than consumed from sys_tms_module_number_series.
function saveWorkOrderLines(string $workOrderRef, array $lines): void {
    $lineNo = 0;
    foreach ($lines as $line) {
        $hasLineData = !empty($line['pickup_location_ref']) || !empty($line['delivery_location_ref'])
            || !empty($line['vehicle_type_ref'])
            || !empty($line['vehicle_ref']) || !empty($line['driver_ref']);
        if (!$hasLineData) continue;

        $lineNo++;

        supabase_post(SB_API . 't_work_order_lines', [
            'ref' => $workOrderRef . '-L' . $lineNo,
            'work_order_ref' => $workOrderRef,
            'line_no' => $lineNo,
            'pickup_location_ref' => !empty($line['pickup_location_ref']) ? $line['pickup_location_ref'] : null,
            'delivery_location_ref' => !empty($line['delivery_location_ref']) ? $line['delivery_location_ref'] : null,
            'vehicle_type_ref' => !empty($line['vehicle_type_ref']) ? $line['vehicle_type_ref'] : null,
            'vehicle_ref' => !empty($line['vehicle_ref']) ? $line['vehicle_ref'] : null,
            'driver_ref' => !empty($line['driver_ref']) ? $line['driver_ref'] : null,
            'planned_start' => !empty($line['planned_start']) ? $line['planned_start'] : null,
            'planned_end' => !empty($line['planned_end']) ? $line['planned_end'] : null,
            'description' => $line['description'] ?? null,
            'remarks' => $line['remarks'] ?? null,
            'created_by' => current_user()['ref'] ?? null,
            'updated_by' => current_user()['ref'] ?? null,
        ]);
    }
}

