function updateWorkOrders(array $data): array {
    $ref = trim($data['ref'] ?? '');
    if ($ref === '' || !recordExists('m_work_orders', $ref)) {
        return ['error' => 'Record not found.'];
    }

    $wo = supabase_patch(SB_API . 'm_work_orders?ref=eq.' . urlencode($ref), [
        'customer_ref' => !empty($data['customer_ref']) ? $data['customer_ref'] : null,
        'work_order_type_ref' => !empty($data['work_order_type_ref']) ? $data['work_order_type_ref'] : null,
        'quotation_ref' => !empty($data['quotation_ref']) ? $data['quotation_ref'] : null,
        'work_order_status_ref' => !empty($data['work_order_status_ref']) ? $data['work_order_status_ref'] : null,
        'requested_date' => !empty($data['requested_date']) ? $data['requested_date'] : null,
        'planned_start' => !empty($data['planned_start']) ? $data['planned_start'] : null,
        'planned_end' => !empty($data['planned_end']) ? $data['planned_end'] : null,
        'actual_start' => !empty($data['actual_start']) ? $data['actual_start'] : null,
        'actual_end' => !empty($data['actual_end']) ? $data['actual_end'] : null,
        'description' => $data['description'] ?? '',
        'remarks' => $data['remarks'] ?? '',
        'updated_by' => current_user()['ref'] ?? null,
    ]);

    // Replace the line set wholesale: delete every existing child row for this
    // work order ref, then reinsert the current set fresh via the same helper
    // saveWorkOrders() uses — avoids duplicating saveWorkOrderLines()'s ref-naming
    // (workOrderRef . '-L' . lineNo) and null-handling logic.
    supabase_delete(SB_API . 't_work_order_lines?work_order_ref=eq.' . urlencode($ref));
    saveWorkOrderLines($ref, $data['lines'] ?? []);

    return $wo;
}

