function getWorkOrderWithLines(string $ref): array {
    $headers = supabase_get(SB_API . 'm_work_orders?select=ref,customer_ref,work_order_type_ref,quotation_ref,work_order_status_ref,requested_date,planned_start,planned_end,actual_start,actual_end,description,remarks,m_customers(ref,customer_name),m_work_order_types(ref,name),m_work_order_statuses(ref,name)&ref=eq.' . urlencode($ref) . '&limit=1');
    if (empty($headers)) return [];
    $wo = $headers[0];

    $lines = supabase_get(SB_API . 't_work_order_lines?select=ref,line_no,pickup_location_ref,delivery_location_ref,vehicle_type_ref,vehicle_ref,driver_ref,planned_start,planned_end,description,remarks,m_vehicle_types(ref,name),m_vehicles(ref,plate_number),m_drivers(ref,name)&work_order_ref=eq.' . urlencode($ref) . '&order=line_no.asc');

    $locationRefs = array_values(array_unique(array_filter(array_merge(
        array_column($lines, 'pickup_location_ref'),
        array_column($lines, 'delivery_location_ref')
    ))));
    $locationsByRef = [];
    if ($locationRefs) {
        $locations = supabase_get(SB_API . 'm_locations?select=ref,name&ref=in.(' . implode(',', $locationRefs) . ')');
        foreach ($locations as $loc) {
            $locationsByRef[$loc['ref']] = $loc['name'];
        }
    }

    foreach ($lines as &$line) {
        $line['pickup_location_name']   = $line['pickup_location_ref']   ? ($locationsByRef[$line['pickup_location_ref']]   ?? null) : null;
        $line['delivery_location_name'] = $line['delivery_location_ref'] ? ($locationsByRef[$line['delivery_location_ref']] ?? null) : null;
        $line['vehicle_plate'] = $line['m_vehicles']['plate_number'] ?? null;
        $line['driver_name']   = $line['m_drivers']['name']          ?? null;
    }
    unset($line);

    $wo['lines'] = $lines;
    return $wo;
}

